}) {
  const [opened, setOpened] = useState(false);
  const { envConfig } = useEnv();
  const settings = useSettingsStore((s) => s.settings);
  const data = useBookDataStore((s) => s.getBookData(bookKey));
  useEffect(() => setOpened(false), [bookKey]);
  const excerpts = (data?.config?.booknotes ?? []).filter(
    (n) => n.type === 'excerpt' && !n.deletedAt && n.text,
  );
  return (
    <section
      className='flex min-h-[55dvh] flex-col p-3'
      aria-label='책별 노트북'
      data-book-notebook={bookKey.split('-')[0]}
    >
      <button
        type='button'
        className='eink-bordered flex w-full items-center justify-between gap-2 rounded-xl border p-4 text-left'
        aria-expanded={opened}
        onClick={() => setOpened(!opened)}
      >
        <span>
          <strong className='block'>노트북</strong>
          <span className='text-sm break-words'>{data?.book?.title ?? '이 책'}</span>
        </span>
        <span>{opened ? '접기' : '열기'}</span>
      </button>
      {opened && (
        <div className='mt-3 flex min-h-[45dvh] flex-1 flex-col'>
          <NotebookEditor
            bookKey={bookKey}
            handleOpenAnnotations={onAnnotations}
            excerpts={excerpts}
            onDeleteExcerpt={(note) => {
              const store = useBookDataStore.getState();
              const config = store.getConfig(bookKey);
              if (!config) return;
              const notes = (config.booknotes ?? []).map((n) =>
                n.id === note.id ? { ...n, deletedAt: nextBooknoteStamp(n) } : n,
              );
              const updated = store.updateBooknotes(bookKey, notes);
              if (updated) void store.saveConfig(envConfig, bookKey, updated, settings);
            }}
          />
        </div>
      )}
    </section>
  );
}

