/* rEadiT chrome: deliberately scoped away from book text and user CSS. */
:root {
  --readit-paper: color-mix(in oklab, var(--color-base-100) 93%, #dfc99c);
  --readit-wash: color-mix(in oklab, var(--color-base-200) 94%, #b9c8ba);
  --readit-ink: var(--color-base-content);
  --readit-line: color-mix(in oklab, var(--color-base-content) 14%, transparent);
  --readit-accent: color-mix(in oklab, var(--color-base-content) 60%, #658577);
  --readit-radius: 18px;
}
.readit-library {
  background: var(--readit-paper) !important;
}
.readit-library-header {
  background: var(--readit-paper);
  border-bottom: 1px solid var(--readit-line);
}
.readit-wordmark {
  font-size: 25px;
  font-weight: 750;
  letter-spacing: -1.3px;
  line-height: 1;
  display: block;
}
.readit-brand-caption {
  display: block;
  font-size: 10px;
  letter-spacing: 0.12em;
  margin-top: 6px;
  opacity: 0.62;
}
.readit-brand-mark {
  object-fit: contain;
  flex-shrink: 0;
  width: 43px;
  height: 43px;
}
.readit-library-count {
  font-size: 11px;
  white-space: nowrap;
  opacity: 0.6;
  letter-spacing: 0.03em;
}
.readit-library .search-input {
  background: var(--color-base-100);
  border: 1px solid var(--readit-line);
  font-weight: 450;
}
.readit-library [aria-label='정렬 및 필터'],
.readit-library [aria-label='Settings Menu'] {
  border-radius: 13px;
}
.readit-library .recent-shelf {
  margin: 14px 12px 4px;
  padding-top: 14px;
  border: 1px solid var(--readit-line);
  border-radius: 22px;
