}
.readit-library .library-grid-item h4 {
  white-space: normal;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  font-size: 12px;
  line-height: 1.4;
  min-height: 2.8em;
  font-weight: 600;
}
.readit-library .library-list-item {
  padding: 12px;
  border: 1px solid var(--readit-line);
  border-radius: var(--readit-radius);
  background: var(--color-base-100);
}
.readit-library [data-book-hash] {
  border-radius: 14px;
}
.readit-library button:focus-visible,
.readit-settings button:focus-visible,
.readit-help button:focus-visible {
  outline: 2px solid var(--readit-accent);
  outline-offset: 3px;
}
.readit-settings .modal-box {
  border-radius: 28px 28px 0 0;
  background: var(--readit-paper) !important;
}
.readit-settings-header {
  border-bottom: 1px solid var(--readit-line);
  padding: 3px 0 10px;
}
.readit-settings-category {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  flex-direction: column;
  background: transparent !important;
  border: 1px solid transparent;
  font-size: 12px;
  line-height: 1.3;
}
.readit-settings-category[aria-pressed='true'] {
  border-color: var(--readit-line);
  background: var(--color-base-100) !important;
  box-shadow: 0 2px 6px #00000005;
  font-weight: 700;
}
.readit-settings-category svg {
  color: var(--readit-accent);
}
.readit-settings .readit-subtabs {
  padding-top: 4px;
  gap: 4px;
}
.readit-settings .readit-subtabs button {
  border-radius: 10px;
  font-size: 12px;
  min-height: 40px;
}
.readit-settings .readit-subtabs .btn-active {
  background: var(--readit-wash);
  border-bottom: 2px solid var(--readit-accent);
}
.readit-panel-intro {
  padding: 20px 16px 6px;
}
.readit-eyebrow {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.15em;
  opacity: 0.5;
}
.readit-panel-intro h2 {
  font-size: 23px;
  font-weight: 700;
  letter-spacing: -0.045em;
  margin: 6px 0;
}
.readit-panel-intro p {
  font-size: 12px;
  opacity: 0.65;
  line-height: 1.5;
}
.readit-settings .readit-settings-card {
  border-radius: 16px;
  border-color: var(--readit-line);
  overflow: hidden;
  box-shadow: none;
}
.readit-settings .readit-setting-row {
  min-height: 58px;
  font-size: 14px;
}
.readit-settings .readit-setting-row input[type='range'] {
  color: var(--readit-accent);
}
.readit-settings .tips {
  border-radius: 14px;
}
.readit-reader-toolbar {
  border-top: 1px solid var(--readit-line);
  padding-top: 4px;
}
.readit-reader-tabs [role='button'] {
  border-radius: 16px;
  border: 1px solid transparent;
}
.readit-reader-tabs [role='button'].bg-base-300\/85 {
  border-color: var(--readit-line);
}
.readit-notebook-body {
  background: var(--color-base-100);
}
.readit-notebook-paper textarea {
  line-height: 1.85 !important;
  font-size: 16px;
  padding: 0 !important;
}
.readit-help {
  background: var(--readit-paper);
}
.readit-help-topic {
  border: 1px solid var(--readit-line);
  border-radius: 16px;
  background: var(--color-base-100);
  text-align: start;
}
.readit-help-detail {
  background: var(--readit-paper);
}
.readit-help-figure {
  border: 1px solid var(--readit-line);
  border-radius: 14px;
  overflow: hidden;
  background: var(--color-base-100);
  margin: 12px 0;
}
.readit-help-figure img {
  width: 100%;
  height: auto;
  max-height: 310px;
  object-fit: contain;
}
.readit-help-figure figcaption {
  padding: 8px 12px;
  font-size: 11px;
  line-height: 1.5;
  opacity: 0.7;
}
[data-eink='true']
  :is(
    .readit-library,
    .readit-library-header,
    .readit-help,
    .readit-help-detail,
    .readit-settings .modal-box
  ) {
  background: var(--color-base-100) !important;
}
[data-eink='true']
  :is(
    .readit-library .recent-shelf,
    .readit-library .library-list-item,
    .readit-settings-category,
    .readit-help-figure
  ) {
  border: 1px solid currentColor;
  background: var(--color-base-100) !important;
  box-shadow: none;
}
[data-eink='true'] .readit-settings-category[aria-pressed='true'] {
  border-width: 2px;
  text-decoration: underline;
}
[data-eink='true'] .readit-library .bookitem-main {
  box-shadow: none;
}
@media (min-width: 640px) {
  .readit-library-header {
    padding-inline: 28px !important;
  }
  .readit-brand-caption {
    font-size: 11px;
  }
  .readit-settings-category {
    flex-direction: row;
  }
  .readit-settings .modal-box {
    border-radius: 26px;
  }
  .readit-library .recent-shelf {
    margin-inline: 24px;
  }
}
@media (prefers-reduced-motion: reduce) {
  :is(.readit-library, .readit-settings, .readit-help) * {
    transition-duration: 0s !important;
    animation-duration: 0s !important;
  }
}

/* Brand accent belongs to the chrome, never to book content. */
:is(
  .readit-library,
  .readit-settings,
  .readit-help,
  [data-personal-settings],
  .readit-reader-toolbar,
  .readit-reader-tabs
) {
  --color-primary: #456b58;
  --color-primary-content: #fff;
  accent-color: #456b58;
}
.theme-dark
  :is(
    .readit-library,
    .readit-settings,
    .readit-help,
    [data-personal-settings],
    .readit-reader-toolbar,
    .readit-reader-tabs
  ) {
  --color-primary: #a9c7b4;
  --color-primary-content: #193526;
  accent-color: #a9c7b4;
}
[data-personal-settings] .btn-primary,
.readit-settings .btn-primary {
  background: var(--color-primary);
  color: var(--color-primary-content);
  border-color: var(--color-primary);
}

