export const DEFAULT_TURN_SENSITIVITY = 60;
export function normalizeTurnSensitivity(value: unknown): number {
  if (value === undefined || value === null || value === '') return DEFAULT_TURN_SENSITIVITY;
  const n = Number(value);
  return Number.isFinite(n) ? Math.round(Math.max(0, Math.min(100, n))) : DEFAULT_TURN_SENSITIVITY;
}
export function turnSensitivityPolicy(value: unknown) {
  const n = normalizeTurnSensitivity(value);
  return {
    claimDistance: 22 - 0.14 * n,
    fastClaimDistance: Math.max(3, 10 - 0.08 * n),
    commitProgress: 0.7 - 0.004 * n,
    flickVelocity: 0.42 - 0.0024 * n,
  };
}
export function shouldCommitSensitiveTurn(
  sample: {
    style: 'curl' | 'slide' | 'push';
    progress: number;
    velocity: number;
    width: number;
    releaseVelocity?: number;
  },
  sensitivity: unknown,
): boolean {
  const p = turnSensitivityPolicy(sensitivity);
  if (
    sample.progress <= 0 ||
    sample.velocity < -p.flickVelocity ||
    (sample.releaseVelocity ?? 0) < -p.flickVelocity
  )
    return false;
  const threshold = sample.velocity < 0 ? Math.max(0.5, p.commitProgress) : p.commitProgress;
  return sample.style === 'curl'
    ? sample.velocity > p.flickVelocity || sample.progress > p.commitProgress
    : sample.progress + (sample.velocity * 240) / Math.max(1, sample.width) > threshold;
}

