import { it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { render, screen, fireEvent, cleanup } from '@testing-library/react';
import { HELP_SCENARIOS } from '@/utils/readitHelp';
import { HELP_IMAGES } from '@/utils/readitHelpImages';
import PersonalGettingStarted from '@/app/library/components/PersonalGettingStarted';
it('ships an actual local WebP crop with accessible text for every detailed help section', () => {
  for (const topic of HELP_SCENARIOS)
    for (const [i] of topic.sections.entries()) {
      const image = HELP_IMAGES[topic.id + '-' + i];
      expect(image?.alt.length).toBeGreaterThan(5);
      expect(image?.caption.length).toBeGreaterThan(5);
      expect(image?.src).toMatch(/^\/readit\/help\/[^/]+\.webp$/);
      const bytes = fs.readFileSync(path.join(process.cwd(), 'public', image!.src.slice(1)));
      expect(bytes.subarray(0, 4).toString()).toBe('RIFF');
      expect(bytes.subarray(8, 12).toString()).toBe('WEBP');
    }
});
it('zooms a cropped example and returns to the same detailed help with Escape', () => {
  render(<PersonalGettingStarted onDone={() => {}} />);
  fireEvent.click(screen.getByRole('button', { name: /책 가져오기/ }));
  fireEvent.click(screen.getByRole('button', { name: '파일로 추가 예시 화면 확대' }));
  expect(screen.getByRole('dialog', { name: '예시 화면 확대' })).toBeTruthy();
  fireEvent.keyDown(window, { key: 'Escape' });
  expect(screen.queryByRole('dialog', { name: '예시 화면 확대' })).toBeNull();
  expect(screen.getByRole('dialog', { name: '책 가져오기 · 감시 폴더' })).toBeTruthy();
  cleanup();
});

