import { it, expect } from 'vitest';
import {
  normalizeTurnSensitivity,
  turnSensitivityPolicy,
  shouldCommitSensitiveTurn,
} from '@/utils/readitTurnSensitivity';
import {
  createTurnGestureIntent,
  shouldClaimTurnGesture,
} from '@/app/reader/utils/turnGestureArena';
it('normalizes saved sensitivity and supplies a slightly easier default', () => {
  expect(normalizeTurnSensitivity(undefined)).toBe(60);
  expect(normalizeTurnSensitivity('oops')).toBe(60);
  expect(normalizeTurnSensitivity(-1)).toBe(0);
  expect(normalizeTurnSensitivity(120)).toBe(100);
  expect(turnSensitivityPolicy(60).commitProgress).toBeLessThan(0.5);
  expect(turnSensitivityPolicy(100).commitProgress).toBeLessThan(
    turnSensitivityPolicy(0).commitProgress,
  );
});
it('makes a short deliberate curl easier without changing forward/backward decisions', () => {
  const sample = { style: 'curl' as const, progress: 0.34, velocity: 0.12, width: 400 };
  expect(shouldCommitSensitiveTurn(sample, 100)).toBe(true);
  expect(shouldCommitSensitiveTurn(sample, 0)).toBe(false);
  expect(shouldCommitSensitiveTurn({ ...sample, progress: 0, velocity: -0.5 }, 100)).toBe(false);
});
it('preserves central coherence, vertical lock and reserved brightness edge at high sensitivity', () => {
  const a = createTurnGestureIntent(0, false, 0);
  expect(shouldClaimTurnGesture(a, { deltaX: 3, deltaY: 0, deltaT: 10 }, 15, 100)).toBe(false);
  expect(shouldClaimTurnGesture(a, { deltaX: 4, deltaY: 0, deltaT: 20 }, 15, 100)).toBe(true);
  const vertical = createTurnGestureIntent(0, false, 0);
  expect(shouldClaimTurnGesture(vertical, { deltaX: 2, deltaY: 12, deltaT: 10 }, 15, 100)).toBe(
    false,
  );
  expect(shouldClaimTurnGesture(vertical, { deltaX: 90, deltaY: 15, deltaT: 40 }, 15, 100)).toBe(
    false,
  );
  const edge = createTurnGestureIntent(1, true, 0);
  expect(shouldClaimTurnGesture(edge, { deltaX: 20, deltaY: 0, deltaT: 10 }, 15, 100)).toBe(false);
});

it('honors an intentional pull-back even with easier sensitivity and a fast initial motion', () => {
  expect(
    shouldCommitSensitiveTurn(
      { style: 'curl', progress: 0.14, velocity: 0.286, releaseVelocity: -0.89, width: 300 },
      60,
    ),
  ).toBe(false);
  expect(
    shouldCommitSensitiveTurn({ style: 'slide', progress: 0.55, velocity: -0.1, width: 300 }, 60),
  ).toBe(false);
});

