import { it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
it('keeps client directives ahead of imports when replacing UI icon modules', () => {
  const root = path.join(process.cwd(), 'src');
  const broken: string[] = [];
  const visit = (dir: string) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const file = path.join(dir, entry.name);
      if (entry.isDirectory() && !entry.name.startsWith('__')) visit(file);
      else if (entry.isFile() && entry.name.endsWith('.tsx')) {
        const text = fs.readFileSync(file, 'utf8');
        const directive = /^\(?['"]use client['"]\)?;?$/m.exec(text);
        if (directive && /\bimport\s/.test(text.slice(0, directive.index)))
          broken.push(path.relative(root, file));
      }
    }
  };
  visit(root);
  expect(broken).toEqual([]);
});
